// Helper to fetch git tree items from a GitHub repo
async function fetchRepoTreeItems(
  octokit: Octokit,
  repoUrl: string,
  prefix: string = ''
): Promise<Array<{ path: string; type: 'blob' | 'tree'; size?: number }>> {
  const repoInfo = parseGitHubRepoUrl(repoUrl);
  if (!repoInfo) return [];

  let defaultBranch = 'main';
  try {
    const { data: repoData } = await octokit.rest.repos.get({
      owner: repoInfo.owner,
      repo: repoInfo.repo,
    });
    defaultBranch = repoData.default_branch || 'main';
  } catch (e) {
    // default to main
  }

  let treeData: any[] = [];
  try {
    const { data } = await octokit.rest.git.getTree({
      owner: repoInfo.owner,
      repo: repoInfo.repo,
      tree_sha: defaultBranch,
      recursive: 'true',
    });
    treeData = data.tree || [];
  } catch (treeErr: any) {
    if (treeErr.status === 404 && defaultBranch === 'main') {
      const { data } = await octokit.rest.git.getTree({
        owner: repoInfo.owner,
        repo: repoInfo.repo,
        tree_sha: 'master',
        recursive: 'true',
      });
      treeData = data.tree || [];
    } else {
      throw treeErr;
    }
  }

  const cleanPrefix = prefix ? (prefix.endsWith('/') ? prefix : `${prefix}/`) : '';

  return treeData
    .filter((item: any) => item.path && item.type)
    .map((item: any) => ({
      path: `${cleanPrefix}${item.path}`,
      type: (item.type === 'tree' ? 'tree' : 'blob') as 'blob' | 'tree',
      size: item.size,
    }));
}

export async function GET(
  req: Request,
  context: { params: Promise<{ name: string }> }
) {
  try {
    const { name: appName } = await context.params;

    const access = await requireAppAccess(appName);
    if (access instanceof NextResponse) return access;

    // 1. Try to proxy to remote backend endpoint first (https://api.quyenlt.com/api/...)
    try {
      let backendRes = await backendFetch(`/api/project/${appName}/files`, { cache: 'no-store' });
      if (!backendRes.ok && backendRes.status === 404) {
        backendRes = await backendFetch(`/api/projects/${appName}/files`, { cache: 'no-store' });
      }
      if (backendRes.ok) {
        const data = await backendRes.json();
        return NextResponse.json(data);
      }
    } catch (e) {
      // Backend not reached or not implementing this endpoint yet, proceed to GitHub fallback
    }

    // 2. Fallback: Fetch directly from GitHub repository (supports 2 repos: FE & BE)
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    let userGithubToken: string | null = null;
    if (userId) {
      const tokenInfo = await getOrRefreshUserGithubToken(userId);
      userGithubToken = tokenInfo?.token || null;
    }

    const project = await prisma.project.findFirst({
      where: { app_name: appName },
    });

    if (!project) {
      return NextResponse.json(
        { error: 'Không tìm thấy dự án trong cơ sở dữ liệu' },
        { status: 404 }
      );
    }

    const octokit = new Octokit({
      auth: userGithubToken || undefined,
    });

    let items: Array<{ path: string; type: 'blob' | 'tree'; size?: number }> = [];

    const isFullstackTwoRepo =
      (project.arch_type === 'fullstack' || Boolean(project.fe_repo_url && project.be_repo_url)) &&
      project.fe_repo_url &&
      project.be_repo_url &&
      project.fe_repo_url !== project.be_repo_url;

    if (isFullstackTwoRepo && project.fe_repo_url && project.be_repo_url) {
      // Fetch both Frontend and Backend repos and namespace them into frontend/ and backend/
      const [feItems, beItems] = await Promise.all([
        fetchRepoTreeItems(octokit, project.fe_repo_url, 'frontend').catch((err) => {
          console.error('Error fetching FE repo tree:', err);
          return [];
        }),
        fetchRepoTreeItems(octokit, project.be_repo_url, 'backend').catch((err) => {
          console.error('Error fetching BE repo tree:', err);
          return [];
        }),
      ]);

      items = [...feItems, ...beItems];
    } else {
      // Single repo or monorepo
      const repoUrl = project.repo_url || project.fe_repo_url || project.be_repo_url;
      if (!repoUrl) {
        return NextResponse.json(
          { error: 'Không tìm thấy thông tin repository của dự án' },
          { status: 404 }
        );
      }
      items = await fetchRepoTreeItems(octokit, repoUrl, '');
    }

    // Check if there are staged local files that were added/edited
    const staged = stagedProjectFiles[appName] || {};
    for (const stagedPath of Object.keys(staged)) {
      if (!items.some((i) => i.path === stagedPath)) {
        items.push({
          path: stagedPath,
          type: 'blob',
          size: staged[stagedPath].length,
        });
      }
    }

    const tree = buildTreeFromPaths(items);
    return NextResponse.json({
      status: 'success',
      tree,
    });
  } catch (error: any) {
    console.error('Failed to get project files:', error);
    return NextResponse.json(
      {
        error:
          error?.message ||
          'Không thể tải danh sách tập tin mã nguồn từ kho lưu trữ',
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { Octokit } from '@octokit/rest';
import { parseGitHubRepoUrl, stagedProjectFiles } from '@/lib/projectFiles';
import { getOrRefreshUserGithubToken, saveUserGithubTokens } from '@/lib/githubToken';
import { backendFetch, requireAppAccess } from '@/lib/backend';

// Helper to detect environment/secret files that should NEVER be committed to git
function isEnvSecretFile(filePath: string): boolean {
  const clean = filePath.replace(/^\/+/, '').toLowerCase();
  const basename = clean.split('/').pop() || '';
  if (
    basename.includes('.example') ||
    basename.includes('.sample') ||
    basename.includes('.template')
  ) {
    return false;
  }
  return basename === '.env' || basename.startsWith('.env.');
}

// Helper to push a set of files to a GitHub repository under authenticated user's account
async function pushFilesToRepo({
  octokit,
  repoUrl,
  customRepoName,
  targetBranch = 'main',
  files,
  commitMessage,
  authUser,
  componentName = 'code',
}: {
  octokit: Octokit;
  repoUrl: string;
  customRepoName?: string;
  targetBranch?: string;
  files: Record<string, string>;
  commitMessage: string;
  authUser: any;
  componentName?: string;
}): Promise<{
  component: string;
  status: string;
  repo_url: string;
  branch: string;
  owner: string;
  message: string;
  commit_sha?: string;
}> {
  const repoInfo = parseGitHubRepoUrl(repoUrl);
  const originalRepo = repoInfo ? repoInfo.repo : 'project-repo';

  // If user specified customRepoName, use it; otherwise use original repo name
  const targetRepo = customRepoName ? customRepoName.trim() : originalRepo;
  const targetOwner = authUser.login;
  const finalBranch = targetBranch.trim() || 'main';

  // 1. Ensure target repo exists on user's account
  let repoExists = false;
  try {
    const { data: existingRepo } = await octokit.rest.repos.get({
      owner: targetOwner,
      repo: targetRepo,
    });
    repoExists = Boolean(existingRepo.id);
  } catch (e) {
    repoExists = false;
  }

  if (!repoExists) {
    // Try to fork from original repo if available, or create new repository
    let forked = false;
    if (repoInfo && repoInfo.owner.toLowerCase() !== targetOwner.toLowerCase()) {
      try {
        await octokit.rest.repos.createFork({
          owner: repoInfo.owner,
          repo: repoInfo.repo,
          name: targetRepo,
        });
        forked = true;
        // Wait for GitHub to initialize fork
        await new Promise((resolve) => setTimeout(resolve, 2500));
      } catch (forkErr) {
        forked = false;
      }
    }

    if (!forked) {
      // Create new repo directly
      try {
        await octokit.rest.repos.createForAuthenticatedUser({
          name: targetRepo,
          auto_init: true,
          description: `Vibe Hosting repository for ${targetRepo}`,
        });
        await new Promise((resolve) => setTimeout(resolve, 2000));
      } catch (createErr: any) {
        throw new Error(
          `Không thể tạo repository ${targetOwner}/${targetRepo} trên GitHub: ${createErr?.message}`
        );
      }
    }
  }

  // 2. Identify default branch & current ref
  let refSha = '';
  try {
    const { data: refData } = await octokit.rest.git.getRef({
      owner: targetOwner,
      repo: targetRepo,
      ref: `heads/${finalBranch}`,
    });
    refSha = refData.object.sha;
  } catch (refErr: any) {
    // If targetBranch (e.g. main) does not exist yet, try to find master or default branch
    let fallbackBranch = 'master';
    try {
      const { data: targetRepoData } = await octokit.rest.repos.get({
        owner: targetOwner,
        repo: targetRepo,
      });
      fallbackBranch = targetRepoData.default_branch || 'master';
    } catch (e) {
      fallbackBranch = 'master';
    }

    try {
      const { data: fallbackRef } = await octokit.rest.git.getRef({
        owner: targetOwner,
        repo: targetRepo,
        ref: `heads/${fallbackBranch}`,
      });
      refSha = fallbackRef.object.sha;

      // Create target branch ref
      try {
        await octokit.rest.git.createRef({
          owner: targetOwner,
          repo: targetRepo,
          ref: `refs/heads/${finalBranch}`,
          sha: refSha,
        });
      } catch (createRefErr) {
        // ref might already exist
      }
    } catch (e) {
      // Empty repo without commits
    }
  }

  // 3. Base tree SHA
  let baseTreeSha: string | undefined = undefined;
  if (refSha) {
    try {
      const { data: baseCommit } = await octokit.rest.git.getCommit({
        owner: targetOwner,
        repo: targetRepo,
        commit_sha: refSha,
      });
      baseTreeSha = baseCommit.tree.sha;
    } catch (e) {
      baseTreeSha = undefined;
    }
  }

  let targetTreeSha = baseTreeSha;
  const fileKeys = Object.keys(files);

  // 4. Create blobs and tree
  if (fileKeys.length > 0) {
    const rawItems = await Promise.all(
      fileKeys.map(async (rawFilePath) => {
        // GitHub Git Trees API requires path to NOT start with a slash
        const cleanPath = rawFilePath.replace(/^\/+/, '').trim();
        // Never push secret env files to GitHub (violates GitHub Secret Scanning)
        if (!cleanPath || isEnvSecretFile(cleanPath)) return null;

        const fileContent = files[rawFilePath];
        try {
          const { data: blob } = await octokit.rest.git.createBlob({
            owner: targetOwner,
            repo: targetRepo,
            content: Buffer.from(fileContent).toString('base64'),
            encoding: 'base64',
          });
          return {
            path: cleanPath,
            mode: '100644' as const,
            type: 'blob' as const,
            sha: blob.sha,
          };
        } catch (blobErr: any) {
          const errorMsg =
            blobErr?.response?.data?.message || blobErr?.message || '';
          console.error(`[PUSH] createBlob failed for "${cleanPath}":`, errorMsg);
          if (
            errorMsg.includes('Secret detected') ||
            errorMsg.includes('Repository rule violations') ||
            blobErr?.status === 422
          ) {
            throw new Error(
              `GitHub Secret Scanning từ chối tập tin "${cleanPath}" vì phát hiện có chứa Secret / Token bí mật (ví dụ: OpenAI API Key, Private Key, PAT). Vui lòng xóa Secret khỏi file (sử dụng GitHub Secrets) trước khi push.`
            );
          }
          throw blobErr;
        }
      })
    );

    const treeItems = rawItems.filter(Boolean) as Array<{
      path: string;
      mode: '100644';
      type: 'blob';
      sha: string;
    }>;

    if (treeItems.length > 0) {
      const { data: newTree } = await octokit.rest.git.createTree({
        owner: targetOwner,
        repo: targetRepo,
        base_tree: baseTreeSha,
        tree: treeItems,
      });

      targetTreeSha = newTree.sha;
    }
  }

  const finalCommitMessage = commitMessage.trim() || 'fix(code): update via Vibe Hosting File Manager';

  // 5. Create commit
  const commitParams: any = {
    owner: targetOwner,
    repo: targetRepo,
    message: finalCommitMessage,
    tree: targetTreeSha || '',
  };
  if (refSha) {
    commitParams.parents = [refSha];
  }

  const { data: newCommit } = await octokit.rest.git.createCommit(commitParams);

  // 6. Update reference
  try {
    await octokit.rest.git.updateRef({
      owner: targetOwner,
      repo: targetRepo,
      ref: `heads/${finalBranch}`,
      sha: newCommit.sha,
      force: true,
    });
  } catch (updateErr) {
    await octokit.rest.git.createRef({
      owner: targetOwner,
      repo: targetRepo,
      ref: `refs/heads/${finalBranch}`,
      sha: newCommit.sha,
    });
  }

  const finalRepoUrl = `https://github.com/${targetOwner}/${targetRepo}`;
  const displayComp = componentName === 'be' || componentName === 'backend' ? 'BACKEND' : componentName === 'fe' || componentName === 'frontend' ? 'FRONTEND' : 'PROJECT';

  return {
    component: componentName === 'be' ? 'backend' : componentName === 'fe' ? 'frontend' : componentName,
    status: 'success',
    repo_url: finalRepoUrl,
    branch: finalBranch,
    owner: targetOwner,
    message: `[${displayComp}] Đã chuyển remote và push thành công lên ${finalRepoUrl} (nhánh ${finalBranch})`,
    commit_sha: newCommit.sha,
  };
}

export async function POST(
  req: Request,
  context: { params: Promise<{ name: string }> }
) {
  try {
    const { name: appName } = await context.params;

    const access = await requireAppAccess(appName);
    if (access instanceof NextResponse) return access;
    const body = await req.json();
    const {
      githubToken,
      commitMessage = 'Update via Vibe Hosting File Manager',
      repoName,
      targetBranch = 'main',
      component = '',
      autoRebuild = true,
      files,
    } = body;

    let activeToken = (typeof githubToken === 'string' && githubToken.trim().length > 0) ? githubToken.trim() : null;

    if (!activeToken) {
      const session = await getServerSession(authOptions);
      const userId = (session?.user as any)?.id;
      if (userId) {
        const tokenInfo = await getOrRefreshUserGithubToken(userId);
        if (tokenInfo?.token) {
          activeToken = tokenInfo.token;
        }
      }
    }

    if (!activeToken) {
      return NextResponse.json(
        { error: 'GitHub Token là bắt buộc để đẩy code lên GitHub. Vui lòng kết nối tài khoản GitHub hoặc nhập PAT.' },
        { status: 400 }
      );
    }


    // 1. Try remote Backend API endpoint first
    try {
      let backendRes = await backendFetch(`/api/project/${appName}/github/push`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          githubToken: activeToken,
          commitMessage,
          repoName,
          targetBranch,
          component,
          autoRebuild,
          files,
        }),
      });

      if (!backendRes.ok && backendRes.status === 404) {
        backendRes = await backendFetch(`/api/projects/${appName}/github/push`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            githubToken: activeToken,
            commitMessage,
            repoName,
            targetBranch,
            component,
            autoRebuild,
            files,
          }),
        });
      }

      if (backendRes.status !== 404) {
        const rawText = await backendRes.text();
        let data: any = null;
        try {
          data = JSON.parse(rawText);
        } catch {
          data = null;
        }

        if (backendRes.ok && data) {
          delete stagedProjectFiles[appName];

          // Sync database with updated repo URLs returned by Backend
          if (Array.isArray(data.results)) {
            for (const r of data.results) {
              if (r.repo_url) {
                if (r.component === 'backend' || r.component === 'be') {
                  await prisma.project.updateMany({
                    where: { app_name: appName },
                    data: { be_repo_url: r.repo_url, repo_url: r.repo_url },
                  }).catch(() => {});
                } else if (r.component === 'frontend' || r.component === 'fe') {
                  await prisma.project.updateMany({
                    where: { app_name: appName },
                    data: { fe_repo_url: r.repo_url },
                  }).catch(() => {});
                } else {
                  await prisma.project.updateMany({
                    where: { app_name: appName },
                    data: { repo_url: r.repo_url },
                  }).catch(() => {});
                }
              }
            }
          }

          return NextResponse.json(data);
        } else {
          // Forward backend error response
          const errorMsg =
            data?.detail ||
            data?.message ||
            data?.error ||
            (backendRes.status === 401
              ? 'Token không hợp lệ hoặc thiếu quyền "repo"'
              : `Máy chủ Backend trả về lỗi (${backendRes.status}): ${rawText.slice(0, 150)}`);
          return NextResponse.json({ error: errorMsg }, { status: backendRes.status });
        }
      }
    } catch (e) {
      // Backend not reached or returned 404, fallback to Octokit implementation
    }

    // 2. Direct GitHub Push Fallback Implementation
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (userId) {
      saveUserGithubTokens(userId, { accessToken: activeToken }).catch(() => {});
    }

    const project = await prisma.project.findFirst({
      where: { app_name: appName },
    });

    if (!project) {
      return NextResponse.json({ error: 'Không tìm thấy thông tin dự án' }, { status: 404 });
    }

    const octokit = new Octokit({ auth: activeToken });

    // Validate token and fetch user identity
    let authUser: any;
    try {
      const { data } = await octokit.rest.users.getAuthenticated();
      authUser = data;
    } catch (authErr: any) {
      return NextResponse.json(
        {
          error:
            'GitHub Token không hợp lệ hoặc đã hết hạn. Vui lòng kiểm tra lại token có quyền "repo".',
        },
        { status: 401 }
      );
    }

    const staged: Record<string, string> = {};
    if (stagedProjectFiles[appName]) {
      for (const [k, v] of Object.entries(stagedProjectFiles[appName])) {
        const clean = k.replace(/^\/+/, '').trim();
        if (isEnvSecretFile(clean)) {
          // Purge secret env files from memory cache so they are never committed to git
          delete stagedProjectFiles[appName][k];
        } else if (clean) {
          staged[clean] = v;
        }
      }
    }

    // Merge files directly sent from editor (skip .env secret files)
    if (Array.isArray(files)) {
      for (const f of files) {
        if (f && f.path && typeof f.content === 'string') {
          const clean = f.path.replace(/^\/+/, '').trim();
          if (clean && !isEnvSecretFile(clean)) {
            staged[clean] = f.content;
            if (!stagedProjectFiles[appName]) stagedProjectFiles[appName] = {};
            stagedProjectFiles[appName][clean] = f.content;
          }
        }
      }
    }

    const isFullstackTwoRepo =
      (project.arch_type === 'fullstack' || Boolean(project.fe_repo_url && project.be_repo_url)) &&
      project.fe_repo_url &&
      project.be_repo_url &&
      project.fe_repo_url !== project.be_repo_url;

    const results: Array<{
      component: string;
      status: string;
      repo_url: string;
      branch: string;
      owner: string;
      message: string;
    }> = [];

    if (isFullstackTwoRepo && project.fe_repo_url && project.be_repo_url) {
      const feFiles: Record<string, string> = {};
      const beFiles: Record<string, string> = {};

      for (const [filePath, content] of Object.entries(staged)) {
        const cleanPath = filePath.replace(/^\/+/, '').trim();
        if (!cleanPath) continue;

        if (cleanPath.startsWith('frontend/')) {
          const rel = cleanPath.replace(/^frontend\//, '').replace(/^\/+/, '');
          if (rel) feFiles[rel] = content;
        } else if (cleanPath.startsWith('backend/')) {
          const rel = cleanPath.replace(/^backend\//, '').replace(/^\/+/, '');
          if (rel) beFiles[rel] = content;
        } else {
          // Put root files in both or target
          if (component === 'fe') feFiles[cleanPath] = content;
          else if (component === 'be') beFiles[cleanPath] = content;
          else {
            feFiles[cleanPath] = content;
            beFiles[cleanPath] = content;
          }
        }
      }

      // Check which components to push
      const shouldPushBe = component === '' || component === 'be';
      const shouldPushFe = component === '' || component === 'fe';

      if (shouldPushBe) {
        const beRepoName = repoName || parseGitHubRepoUrl(project.be_repo_url)?.repo;
        const res = await pushFilesToRepo({
          octokit,
          repoUrl: project.be_repo_url,
          customRepoName: beRepoName,
          targetBranch,
          files: beFiles,
          commitMessage,
          authUser,
          componentName: 'backend',
        });
        results.push(res);
        await prisma.project
          .update({
            where: { id: project.id },
            data: { be_repo_url: res.repo_url },
          })
          .catch(() => {});
      }

      if (shouldPushFe) {
        const feRepoName = repoName ? `${repoName}_FE` : parseGitHubRepoUrl(project.fe_repo_url)?.repo;
        const res = await pushFilesToRepo({
          octokit,
          repoUrl: project.fe_repo_url,
          customRepoName: feRepoName,
          targetBranch,
          files: feFiles,
          commitMessage,
          authUser,
          componentName: 'frontend',
        });
        results.push(res);
        await prisma.project
          .update({
            where: { id: project.id },
            data: { fe_repo_url: res.repo_url },
          })
          .catch(() => {});
      }
    } else {
      // Single repo or Monorepo
      const repoUrl = project.repo_url || project.fe_repo_url || project.be_repo_url;
      if (!repoUrl) {
        return NextResponse.json({ error: 'Không tìm thấy repository của dự án' }, { status: 404 });
      }

      const res = await pushFilesToRepo({
        octokit,
        repoUrl,
        customRepoName: repoName,
        targetBranch,
        files: staged,
        commitMessage,
        authUser,
        componentName: 'backend',
      });
      results.push(res);

      await prisma.project
        .update({
          where: { id: project.id },
          data: { repo_url: res.repo_url },
        })
        .catch(() => {});
    }

    // Clear staged files on successful push
    delete stagedProjectFiles[appName];

    if (autoRebuild) {
      try {
        backendFetch(`/api/apps/${appName}/redeploy`, { method: 'POST' }).catch(() => {});
      } catch (e) {}
    }

    const mainMessage =
      results.length === 1
        ? results[0].message
        : `Đã chuyển remote và push thành công lên ${results.map((r) => r.repo_url).join(' và ')}`;

    return NextResponse.json({
      status: 'success',
      user: authUser.login,
      rebuild_triggered: Boolean(autoRebuild),
      results,
      message: mainMessage,
    });
  } catch (error: any) {
    console.error('Failed to push to GitHub:', error);
    return NextResponse.json(
      {
        error:
          error?.message ||
          'Không thể đẩy code lên GitHub. Vui lòng kiểm tra lại quyền hạn của GitHub Token.',
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { Octokit } from '@octokit/rest';
import { backendFetch, getBackendBaseUrl, requireAppAccess } from '@/lib/backend';

function webhookConfig(url: string) {
  return {
    url,
    content_type: 'json',
    insecure_ssl: '0',
    // Cùng giá trị GITHUB_WEBHOOK_SECRET với backend; GitHub dùng nó để ký X-Hub-Signature-256
    ...(process.env.GITHUB_WEBHOOK_SECRET ? { secret: process.env.GITHUB_WEBHOOK_SECRET } : {}),
  };
}

function parseGitHubRepoUrl(repoUrl: string): { owner: string; repo: string } | null {
  try {
    const match = repoUrl.match(/github\.com[:/]([^/]+)\/([^/.]+)/);
    if (match) {
      return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
    }
  } catch (e) {
    console.error('Error parsing repo URL:', e);
  }
  return null;
}

export async function GET(
  req: Request,
  context: { params: Promise<{ name: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { name: appName } = await context.params;

    const access = await requireAppAccess(appName);
    if (access instanceof NextResponse) return access;

    // Get backend config
    let autoCicd = false;
    try {
      const res = await backendFetch(`/api/apps/${appName}/config`);
      if (res.ok) {
        const data = await res.json();
        if (data && data.data && typeof data.data.auto_cicd === 'boolean') {
          autoCicd = data.data.auto_cicd;
        } else if (data && typeof data.auto_cicd === 'boolean') {
          autoCicd = data.auto_cicd;
        }
      }
    } catch (e) {
      console.error(`Error fetching backend config for ${appName}:`, e);
    }

    // Check user github token and project
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { githubToken: true, githubUsername: true },
    });

    const project = await prisma.project.findFirst({
      where: { app_name: appName },
    });

    const hasGithubToken = Boolean(user?.githubToken);
    const targetWebhookUrl = `${getBackendBaseUrl()}/api/webhooks/github/${appName}`;

    // If project has auto_cicd as false in database, always enforce false and sync backend
    if (project && !project.auto_cicd) {
      if (autoCicd) {
        autoCicd = false;
        backendFetch(`/api/apps/${appName}/config`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ auto_cicd: false }),
        }).catch(() => {});
      }
    } else if (project?.auto_cicd && user?.githubToken && project?.repo_url) {
      // If user enabled auto_cicd, verify real webhook status on GitHub
      const repoInfo = parseGitHubRepoUrl(project.repo_url);
      if (repoInfo) {
        try {
          const octokit = new Octokit({ auth: user.githubToken });
          const { data: webhooks } = await octokit.rest.repos.listWebhooks({
            owner: repoInfo.owner,
            repo: repoInfo.repo,
          });
          const hasActiveHook = webhooks.some(
            (h: any) => h.config?.url === targetWebhookUrl && h.active
          );

          // Webhook tạo trước khi có secret: bổ sung secret để backend xác minh được chữ ký
          const unsignedHook = webhooks.find(
            (h: any) => h.config?.url === targetWebhookUrl && h.active && !h.config?.secret
          );
          if (unsignedHook && process.env.GITHUB_WEBHOOK_SECRET) {
            await octokit.rest.repos.updateWebhook({
              owner: repoInfo.owner,
              repo: repoInfo.repo,
              hook_id: unsignedHook.id,
              config: webhookConfig(targetWebhookUrl),
            }).catch((e: any) => console.error('Failed to add webhook secret:', e));
          }

          if (!hasActiveHook) {
            autoCicd = false;
            backendFetch(`/api/apps/${appName}/config`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ auto_cicd: false }),
            }).catch(() => {});
            await prisma.project.update({
              where: { id: project.id },
              data: { auto_cicd: false },
            }).catch(() => {});
          } else {
            autoCicd = true;
          }
        } catch (e) {
          // If token doesn't have permissions, respect database auto_cicd
        }
      }
    }

    return NextResponse.json({
      success: true,
      auto_cicd: autoCicd,
      hasGithubToken,
      githubUsername: user?.githubUsername || null,
    });
  } catch (error) {
    console.error('Failed to get CI/CD state:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

export async function POST(
  req: Request,
  context: { params: Promise<{ name: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;
    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { name: appName } = await context.params;

    const access = await requireAppAccess(appName);
    if (access instanceof NextResponse) return access;
    const body = await req.json();
    const { auto_cicd } = body;

    if (typeof auto_cicd !== 'boolean') {
      return NextResponse.json({ error: 'auto_cicd must be a boolean' }, { status: 400 });
    }

    const targetWebhookUrl = `${getBackendBaseUrl()}/api/webhooks/github/${appName}`;

    // 1. Update backend config first
    const backendRes = await backendFetch(`/api/apps/${appName}/config`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ auto_cicd }),
    });

    if (!backendRes.ok) {
      const errData = await backendRes.json().catch(() => ({}));
      return NextResponse.json(
        { error: errData.detail || errData.message || 'Không thể cập nhật cấu hình trên máy chủ' },
        { status: backendRes.status }
      );
    }

    // 2. Automate GitHub Webhook via User's GitHub Token
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { githubToken: true, githubUsername: true },
    });

    const project = await prisma.project.findFirst({
      where: { app_name: appName },
    });

    if (project) {
      await prisma.project.update({
        where: { id: project.id },
        data: { auto_cicd },
      }).catch((e) => console.error('Failed to update project auto_cicd:', e));
    }

    let webhookSynced = false;
    let githubNotice = '';

    if (!user?.githubToken) {
      githubNotice = 'Chưa liên kết GitHub Token tại trang Profile. Webhook chưa được tự động đăng ký lên GitHub.';
    } else if (!project?.repo_url) {
      githubNotice = 'Không tìm thấy thông tin GitHub repository của dự án.';
    } else {
      const repoInfo = parseGitHubRepoUrl(project.repo_url);
      if (!repoInfo) {
        githubNotice = `Không thể phân tích owner/repo từ URL: ${project.repo_url}`;
      } else {
        const { owner, repo } = repoInfo;
        try {
          const octokit = new Octokit({ auth: user.githubToken });

          // List current webhooks
          const { data: webhooks } = await octokit.rest.repos.listWebhooks({
            owner,
            repo,
          });

          const existingHook = webhooks.find((hook: any) => {
            return hook.config?.url === targetWebhookUrl;
          });

          if (auto_cicd) {
            // Enable webhook
            if (existingHook) {
              // Luôn cập nhật config để webhook cũ (tạo trước khi có secret) cũng được ký
              await octokit.rest.repos.updateWebhook({
                owner,
                repo,
                hook_id: existingHook.id,
                active: true,
                config: webhookConfig(targetWebhookUrl),
              });
            } else {
              await octokit.rest.repos.createWebhook({
                owner,
                repo,
                name: 'web',
                active: true,
                events: ['push'],
                config: webhookConfig(targetWebhookUrl),
              });
            }
            webhookSynced = true;
          } else {
            // Disable webhook
            if (existingHook && existingHook.active) {
              await octokit.rest.repos.updateWebhook({
                owner,
                repo,
                hook_id: existingHook.id,
                active: false,
              });
            }
            webhookSynced = true;
          }
        } catch (githubErr: any) {
          console.error('GitHub Webhook automated sync error:', githubErr);
          if (githubErr.status === 404 || githubErr.status === 403) {
            githubNotice = `Không thể tự cài Webhook lên repo ${owner}/${repo} (Token không có quyền quản trị hoặc repo thuộc tài khoản khác).`;
          } else {
            githubNotice = `Lỗi đồng bộ GitHub: ${githubErr.message || 'Không xác định'}`;
          }
        }
      }
    }

    let message = auto_cicd
      ? 'Đã kích hoạt Auto Deploy (Webhook).'
      : 'Đã tắt Auto Deploy (Webhook).';

    if (webhookSynced && auto_cicd) {
      message = 'Đã kích hoạt Auto Deploy và tự động cài đặt Webhook trên GitHub thành công!';
    } else if (webhookSynced && !auto_cicd) {
      message = 'Đã tắt Auto Deploy và hủy kích hoạt Webhook trên GitHub.';
    } else if (githubNotice) {
      message = `${message} (${githubNotice})`;
    }

    return NextResponse.json({
      success: true,
      auto_cicd,
      webhookSynced,
      message,
      hasGithubToken: Boolean(user?.githubToken),
    });
  } catch (error) {
    console.error('Failed to update CI/CD state:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

