import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { backendFetch } from '@/lib/backend';

async function getAuthenticatedUserId(): Promise<string | null> {
  try {
    const session = await getServerSession(authOptions);
    let userId = (session?.user as any)?.id;

    if (!userId && session?.user) {
      const dbUser = await prisma.user.findFirst({
        where: {
          OR: [
            ...(session.user.email ? [{ email: session.user.email }] : []),
            ...(session.user.name ? [{ username: session.user.name }] : []),
          ],
        },
      });
      if (dbUser) userId = dbUser.id;
    }

    return userId || null;
  } catch (err) {
    console.error("Error resolving authenticated user:", err);
    return null;
  }
}

export async function GET() {
  try {
    const userId = await getAuthenticatedUserId();

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    let projects = await prisma.project.findMany({
      where: { userId },
      orderBy: { createdAt: "desc" },
    });

    // Format response to match Project interface (createdAt as epoch milliseconds)
    const formatted = projects.map((p) => ({
      id: p.id,
      app_name: p.app_name,
      repo_url: p.repo_url,
      app_domain: p.app_domain,
      status: p.status,
      arch_type: p.arch_type,
      db_type: p.db_type,
      be_repo_url: p.be_repo_url,
      fe_repo_url: p.fe_repo_url,
      be_domain: p.be_domain,
      fe_domain: p.fe_domain,
      auto_cicd: p.auto_cicd,
      createdAt: new Date(p.createdAt).getTime(),
    }));

    return NextResponse.json(formatted);
  } catch (error) {
    console.error("Failed to fetch projects:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function POST(req: Request) {
  try {
    const userId = await getAuthenticatedUserId();

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const {
      app_name,
      repo_url,
      app_domain,
      status,
      arch_type,
      db_type,
      be_repo_url,
      fe_repo_url,
      be_domain,
      fe_domain,
    } = body;

    const resolvedRepoUrl = repo_url || fe_repo_url || be_repo_url;
    const resolvedDomain = app_domain || fe_domain || be_domain;

    if (!app_name || !resolvedRepoUrl || !resolvedDomain) {
      return NextResponse.json(
        { error: "Missing required fields: app_name, repo_url/fe_repo_url, app_domain/fe_domain" },
        { status: 400 }
      );
    }

    // Tên app là định danh duy nhất trên K3s, không cho trùng với app của người khác
    const takenByOther = await prisma.project.findFirst({
      where: { app_name, NOT: { userId } },
      select: { id: true },
    });
    if (takenByOther) {
      return NextResponse.json({ error: "Tên ứng dụng đã được người khác sử dụng" }, { status: 409 });
    }

    // Check if project already exists for this user, if so update it
    const existing = await prisma.project.findFirst({
      where: { app_name, userId },
    });

    let record;
    if (existing) {
      record = await prisma.project.update({
        where: { id: existing.id },
        data: {
          repo_url: resolvedRepoUrl,
          app_domain: resolvedDomain,
          status: status || existing.status,
          arch_type: arch_type || existing.arch_type,
          db_type: db_type || existing.db_type,
          be_repo_url: be_repo_url || existing.be_repo_url,
          fe_repo_url: fe_repo_url || existing.fe_repo_url,
          be_domain: be_domain || existing.be_domain,
          fe_domain: fe_domain || existing.fe_domain,
        },
      });
    } else {
      record = await prisma.project.create({
        data: {
          app_name,
          repo_url: resolvedRepoUrl,
          app_domain: resolvedDomain,
          status: status || "deploying",
          arch_type: arch_type || "web_only",
          db_type: db_type || null,
          be_repo_url: be_repo_url || null,
          fe_repo_url: fe_repo_url || null,
          be_domain: be_domain || null,
          fe_domain: fe_domain || null,
          auto_cicd: false,
          userId,
        },
      });

      // Default auto_cicd to false on backend config for newly created projects
      try {
        backendFetch(`/api/apps/${app_name}/config`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ auto_cicd: false }),
        }).catch((e) => console.error("Failed to default auto_cicd on backend:", e));
      } catch (e) {
        console.error("Backend config sync error:", e);
      }
    }

    return NextResponse.json(
      {
        id: record.id,
        app_name: record.app_name,
        repo_url: record.repo_url,
        app_domain: record.app_domain,
        status: record.status,
        arch_type: record.arch_type,
        db_type: record.db_type,
        be_repo_url: record.be_repo_url,
        fe_repo_url: record.fe_repo_url,
        be_domain: record.be_domain,
        fe_domain: record.fe_domain,
        auto_cicd: record.auto_cicd,
        createdAt: new Date(record.createdAt).getTime(),
      },
      { status: existing ? 200 : 201 }
    );
  } catch (error: any) {
    console.error("Failed to create or update project:", error);
    return NextResponse.json({ error: error?.message || "Internal Server Error" }, { status: 500 });
  }
}

export async function DELETE(req: Request) {
  try {
    const userId = await getAuthenticatedUserId();

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { searchParams } = new URL(req.url);
    const id = searchParams.get("id");

    if (!id) {
      return NextResponse.json({ error: "Project ID is required" }, { status: 400 });
    }

    // Ensure the project belongs to the user
    const existing = await prisma.project.findFirst({
      where: { id, userId },
    });

    if (!existing) {
      return NextResponse.json({ error: "Project not found or unauthorized" }, { status: 404 });
    }

    await prisma.project.delete({
      where: { id },
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Failed to delete project:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function PATCH(req: Request) {
  try {
    const userId = await getAuthenticatedUserId();

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const { id, app_name, status } = body;

    if ((!id && !app_name) || !status) {
      return NextResponse.json({ error: "id or app_name, and status are required" }, { status: 400 });
    }

    const existing = await prisma.project.findFirst({
      where: id ? { id, userId } : { app_name, userId },
    });

    if (!existing) {
      return NextResponse.json({ error: "Project not found or unauthorized" }, { status: 404 });
    }

    const updated = await prisma.project.update({
      where: { id: existing.id },
      data: { status },
    });

    return NextResponse.json({
      id: updated.id,
      app_name: updated.app_name,
      repo_url: updated.repo_url,
      app_domain: updated.app_domain,
      status: updated.status,
      createdAt: new Date(updated.createdAt).getTime(),
    });
  } catch (error) {
    console.error("Failed to update project status:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import crypto from 'crypto';
import { saveUserGithubTokens } from '@/lib/githubToken';

export async function GET(req: Request) {
  const reqUrl = new URL(req.url);
  const code = reqUrl.searchParams.get('code');
  const stateRaw = reqUrl.searchParams.get('state');

  if (!code || !stateRaw) {
    return NextResponse.redirect(new URL('/profile?error=missing_oauth_code', req.url));
  }

  try {
    // 1. Xác thực state payload chống CSRF
    const secret = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET;
    if (!secret) {
      return NextResponse.redirect(new URL('/profile?error=invalid_oauth_state', req.url));
    }
    const decodedState = JSON.parse(Buffer.from(stateRaw, 'base64url').toString('utf-8'));
    const { payload, hmac } = decodedState;

    const expectedHmac = crypto.createHmac('sha256', secret).update(payload).digest('hex');
    if (hmac !== expectedHmac) {
      return NextResponse.redirect(new URL('/profile?error=invalid_oauth_state', req.url));
    }

    const { userId, returnTo } = JSON.parse(payload);
    if (!userId) {
      return NextResponse.redirect(new URL('/profile?error=invalid_user_session', req.url));
    }

    // 2. Trao đổi authorization code lấy access_token
    const clientId = process.env.GITHUB_CLIENT_ID;
    const clientSecret = process.env.GITHUB_CLIENT_SECRET;

    if (!clientId || !clientSecret) {
      return NextResponse.redirect(new URL('/profile?error=missing_oauth_credentials', req.url));
    }

    const tokenRes = await fetch('https://github.com/login/oauth/access_token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: JSON.stringify({
        client_id: clientId,
        client_secret: clientSecret,
        code,
      }),
    });

    const tokenData = await tokenRes.json();
    if (!tokenRes.ok || !tokenData.access_token) {
      console.error('GitHub access_token exchange failed:', tokenData);
      return NextResponse.redirect(
        new URL(`/profile?error=token_exchange_failed&desc=${encodeURIComponent(tokenData.error_description || '')}`, req.url)
      );
    }

    const accessToken = tokenData.access_token;
    const refreshToken = tokenData.refresh_token || null;
    const expiresIn = Number(tokenData.expires_in) || (tokenData.refresh_token ? 28800 : null);
    const expiresAt = expiresIn ? new Date(Date.now() + expiresIn * 1000) : null;

    // 3. Lấy thông tin tài khoản GitHub người dùng vừa liên kết
    const userRes = await fetch('https://api.github.com/user', {
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'User-Agent': 'VibeHosting',
      },
    });

    if (!userRes.ok) {
      return NextResponse.redirect(new URL('/profile?error=fetch_github_user_failed', req.url));
    }

    const githubUser = await userRes.json();

    // 4. Lưu trực tiếp vào Database cho User này kèm Refresh Token và thời hạn
    await saveUserGithubTokens(userId, {
      accessToken,
      refreshToken,
      expiresIn,
      expiresAt,
      githubUsername: githubUser.login,
      githubAvatar: githubUser.avatar_url,
    });

    console.log(`[GitHub OAuth] Successfully connected GitHub @${githubUser.login} for user ${userId} with token expiration at: ${expiresAt ? expiresAt.toISOString() : 'N/A'}`);

    const targetUrl = new URL(returnTo || '/profile', req.url);
    targetUrl.searchParams.set('github_connected', 'success');
    return NextResponse.redirect(targetUrl.toString());
  } catch (error: any) {
    console.error('Error in GitHub OAuth callback:', error);
    return NextResponse.redirect(
      new URL(`/profile?error=oauth_callback_error&message=${encodeURIComponent(error.message || '')}`, req.url)
    );
  }
}

import { NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import crypto from 'crypto';

export async function GET(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.redirect(new URL('/login', req.url));
    }

    const clientId = process.env.GITHUB_CLIENT_ID;
    if (!clientId) {
      return NextResponse.redirect(
        new URL('/profile?error=github_oauth_missing_config', req.url)
      );
    }

    const { searchParams } = new URL(req.url);
    const returnTo = searchParams.get('returnTo') || '/profile';

    // Tạo state payload ký mã hóa chống CSRF
    const secret = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET;
    if (!secret) {
      return NextResponse.redirect(new URL('/profile?error=github_oauth_missing_config', req.url));
    }
    const payload = JSON.stringify({ userId, returnTo, time: Date.now() });
    const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex');
    const state = Buffer.from(JSON.stringify({ payload, hmac })).toString('base64url');

    // Callback URL
    const reqUrl = new URL(req.url);
    const host = req.headers.get('x-forwarded-host') || reqUrl.host;
    const proto = req.headers.get('x-forwarded-proto') || reqUrl.protocol.replace(':', '');
    const redirectUri = `${proto}://${host}/api/user/github/callback`;

    const githubAuthUrl = new URL('https://github.com/login/oauth/authorize');
    githubAuthUrl.searchParams.set('client_id', clientId);
    githubAuthUrl.searchParams.set('redirect_uri', redirectUri);
    githubAuthUrl.searchParams.set('scope', 'repo,read:user,user:email');
    githubAuthUrl.searchParams.set('state', state);

    return NextResponse.redirect(githubAuthUrl.toString());
  } catch (error) {
    console.error('Error initiating GitHub OAuth connect:', error);
    return NextResponse.redirect(new URL('/profile?error=oauth_init_failed', req.url));
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { Octokit } from "@octokit/rest";
import {
  getOrRefreshUserGithubToken,
  refreshUserGithubToken,
  invalidateUserGithubToken,
} from "@/lib/githubToken";

export async function GET(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Tự động kiểm tra và làm mới token nếu đã hết hạn hoặc sắp hết hạn (Token Rotation)
    const tokenInfo = await getOrRefreshUserGithubToken(userId);
    let activeToken = tokenInfo?.token;

    if (!activeToken) {
      return NextResponse.json({
        connected: false,
        repos: [],
        message: "GitHub not connected",
      });
    }

    let user: any = null;
    try {
      user = await prisma.user.findUnique({
        where: { id: userId },
        select: { githubUsername: true, githubRefreshToken: true },
      });
    } catch {
      user = await prisma.user.findUnique({
        where: { id: userId },
        select: { githubUsername: true },
      });
    }

    const { searchParams } = new URL(req.url);
    const query = (searchParams.get("q") || "").toLowerCase().trim();

    // Helper fetch danh sách repos
    const fetchRepos = async (token: string) => {
      const octokit = new Octokit({ auth: token });
      const { data } = await octokit.rest.repos.listForAuthenticatedUser({
        sort: "updated",
        direction: "desc",
        per_page: 100,
        affiliation: "owner,collaborator",
      });
      return data;
    };

    let data;
    try {
      data = await fetchRepos(activeToken);
    } catch (githubErr: any) {
      console.warn("[GitHub Repos] Initial fetch error:", githubErr?.message);

      // Nếu gặp lỗi 401 và user có Refresh Token -> Thực hiện Refresh Token Rotation khẩn cấp và thử lại
      if (githubErr?.status === 401 && user?.githubRefreshToken) {
        console.log(`[GitHub Repos] Received 401 Bad credentials. Attempting emergency Refresh Token Rotation for user ${userId}...`);
        const refreshResult = await refreshUserGithubToken(userId, user.githubRefreshToken);

        if (refreshResult.success) {
          activeToken = refreshResult.accessToken;
          try {
            data = await fetchRepos(activeToken);
          } catch (retryErr: any) {
            console.error("[GitHub Repos] Retry after rotation failed:", retryErr);
            throw retryErr;
          }
        } else {
          console.error("[GitHub Repos] Emergency rotation failed:", refreshResult.errorDescription);
          // Token và Refresh Token thực sự đã bị thu hồi hoàn toàn
          await invalidateUserGithubToken(userId);
          return NextResponse.json(
            {
              connected: false,
              tokenExpired: true,
              error: "Phiên kết nối GitHub đã hết hạn hoàn toàn. Vui lòng kết nối lại tài khoản GitHub.",
              repos: [],
            },
            { status: 401 }
          );
        }
      } else if (githubErr?.status === 401) {
        // Không có refresh token (PAT thủ công bị revoke hoặc hết hạn)
        await invalidateUserGithubToken(userId);
        return NextResponse.json(
          {
            connected: false,
            tokenExpired: true,
            error: "GitHub Token đã bị từ chối (401 Bad credentials). Có thể Token đã hết hạn hoặc bị thu hồi. Vui lòng kết nối lại.",
            repos: [],
          },
          { status: 401 }
        );
      } else {
        throw githubErr;
      }
    }

    let repos = data.map((r: any) => ({
      id: r.id,
      name: r.name,
      full_name: r.full_name,
      description: r.description,
      html_url: r.html_url,
      clone_url: r.clone_url,
      language: r.language,
      is_private: r.private,
      stars: r.stargazers_count,
      forks: r.forks_count,
      updated_at: r.updated_at,
    }));

    if (query) {
      repos = repos.filter(
        (r) =>
          r.name.toLowerCase().includes(query) ||
          r.full_name.toLowerCase().includes(query) ||
          (r.description && r.description.toLowerCase().includes(query))
      );
    }

    return NextResponse.json({
      connected: true,
      githubUsername: user?.githubUsername,
      githubToken: activeToken,
      repos,
    });
  } catch (error) {
    console.error("Failed to process repos request:", error);
    return NextResponse.json({ error: "Failed to fetch repositories from GitHub" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { Octokit } from "@octokit/rest";
import {
  getOrRefreshUserGithubToken,
  saveUserGithubTokens,
  invalidateUserGithubToken,
} from "@/lib/githubToken";

export async function GET() {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Tự động kiểm tra và làm mới token nếu sắp hết hạn
    const tokenInfo = await getOrRefreshUserGithubToken(userId);

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { githubUsername: true, githubAvatar: true },
    });

    return NextResponse.json({
      connected: Boolean(tokenInfo?.token),
      githubToken: tokenInfo?.token || null,
      githubUsername: user?.githubUsername || null,
      githubAvatar: user?.githubAvatar || null,
      expiresAt: tokenInfo?.expiresAt || null,
      refreshed: Boolean(tokenInfo?.refreshed),
    });
  } catch (error) {
    console.error("Failed to fetch GitHub info:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function POST(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const { token } = body;

    if (!token || typeof token !== "string" || token.trim().length === 0) {
      return NextResponse.json(
        { error: "GitHub Personal Access Token is required" },
        { status: 400 }
      );
    }

    const cleanToken = token.trim();

    // Verify token with GitHub API
    let githubUser: any;
    try {
      const octokit = new Octokit({ auth: cleanToken });
      const { data } = await octokit.rest.users.getAuthenticated();
      githubUser = data;
    } catch (githubErr: any) {
      console.error("GitHub verification error:", githubErr);
      return NextResponse.json(
        {
          error:
            githubErr?.message ||
            "Invalid GitHub Personal Access Token. Please check that the token is valid and has 'repo' or 'read:user' permissions.",
        },
        { status: 400 }
      );
    }

    // Save token and GitHub user info to database
    await saveUserGithubTokens(userId, {
      accessToken: cleanToken,
      refreshToken: null,
      expiresAt: null,
      githubUsername: githubUser.login,
      githubAvatar: githubUser.avatar_url,
    });

    return NextResponse.json({
      success: true,
      message: `Connected successfully as @${githubUser.login}`,
      githubUsername: githubUser.login,
      githubAvatar: githubUser.avatar_url,
    });
  } catch (error) {
    console.error("Failed to connect GitHub:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function DELETE() {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    await invalidateUserGithubToken(userId);

    return NextResponse.json({
      success: true,
      message: "GitHub account disconnected successfully",
    });
  } catch (error) {
    console.error("Failed to disconnect GitHub:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { getOrRefreshUserGithubToken } from "@/lib/githubToken";

export async function GET() {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const [user, tokenInfo] = await Promise.all([
      prisma.user.findUnique({
        where: { id: userId },
        select: {
          id: true,
          username: true,
          name: true,
          email: true,
          role: true,
          githubUsername: true,
          githubAvatar: true,
          githubToken: true,
          createdAt: true,
        },
      }),
      getOrRefreshUserGithubToken(userId),
    ]);

    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 });
    }

    return NextResponse.json({
      id: user.id,
      username: user.username,
      name: user.name,
      email: user.email,
      role: user.role,
      githubUsername: user.githubUsername,
      githubAvatar: user.githubAvatar,
      isGithubConnected: Boolean(tokenInfo?.token || user.githubToken),
      createdAt: user.createdAt,
    });
  } catch (error) {
    console.error("Failed to fetch user profile:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

export async function PATCH(req: Request) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as any)?.id;

    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await req.json();
    const { name, email } = body;

    const updated = await prisma.user.update({
      where: { id: userId },
      data: {
        ...(name !== undefined ? { name: String(name).trim() || null } : {}),
        ...(email !== undefined ? { email: String(email).trim() || null } : {}),
      },
      select: {
        id: true,
        username: true,
        name: true,
        email: true,
        role: true,
        githubUsername: true,
        githubAvatar: true,
        githubToken: true,
        createdAt: true,
      },
    });

    return NextResponse.json({
      id: updated.id,
      username: updated.username,
      name: updated.name,
      email: updated.email,
      role: updated.role,
      githubUsername: updated.githubUsername,
      githubAvatar: updated.githubAvatar,
      isGithubConnected: Boolean(updated.githubToken),
      createdAt: updated.createdAt,
    });
  } catch (error) {
    console.error("Failed to update user profile:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

'use client';

import { signIn, useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { Triangle, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';
import { ThemeToggle } from '@/components/ThemeToggle';

import Link from 'next/link';

export default function Login() {
  const { status } = useSession();
  const router = useRouter();

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (status === 'authenticated') {
      router.push('/');
    }
  }, [status, router]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    const res = await signIn('credentials', {
      redirect: false,
      username,
      password,
    });

    if (res?.error) {
      setError('Invalid username or password');
      setIsLoading(false);
    } else {
      router.push('/');
    }
  };

  if (status === 'loading' || status === 'authenticated') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-background p-4 relative overflow-hidden">
      {/* Top right Theme Toggle */}
      <div className="absolute top-5 right-5 z-20">
        <ThemeToggle variant="segmented" />
      </div>

      {/* Background decorations */}
      <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-primary/5 rounded-full blur-[100px]"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-blue-500/5 rounded-full blur-[100px]"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-card/50 backdrop-blur-xl border border-border rounded-2xl shadow-2xl p-8 relative z-10"
      >
        <div className="flex flex-col items-center mb-8">
          <div className="w-12 h-12 bg-foreground text-background flex items-center justify-center rounded-xl mb-6 shadow-lg shadow-foreground/20">
            <Triangle className="w-6 h-6 fill-current" />
          </div>
          <h1 className="text-2xl font-semibold tracking-tight text-foreground mb-2">Welcome Back</h1>
          <p className="text-muted-foreground text-center text-sm">Enter your credentials to access the dashboard.</p>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          {error && (
            <div className="bg-red-500/10 border border-red-500/20 text-red-500 text-sm px-4 py-2.5 rounded-md text-center">
              {error}
            </div>
          )}

          <div className="flex flex-col gap-2">
            <label className="text-sm font-medium">Username</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-background border border-border rounded-md px-3 py-2 outline-none focus:border-foreground focus:ring-1 focus:ring-foreground transition-all text-sm"
              placeholder="admin"
              required
            />
          </div>

          <div className="flex flex-col gap-2 mb-2">
            <label className="text-sm font-medium">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-background border border-border rounded-md px-3 py-2 outline-none focus:border-foreground focus:ring-1 focus:ring-foreground transition-all text-sm"
              placeholder="••••••••"
              required
            />
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className="w-full flex items-center justify-center gap-2 bg-foreground text-background hover:bg-foreground/90 py-2.5 px-4 rounded-lg font-medium transition-all shadow-md active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
          >
            {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            Sign In
          </button>
        </form>

        <div className="mt-6 text-center text-xs text-muted-foreground">
          Accounts are managed by the administrator.
        </div>

        <p className="text-center text-[11px] text-muted-foreground/70 mt-4">
          By signing in, you agree to our Terms of Service and Privacy Policy.
        </p>
      </motion.div>
    </div>
  );
}

