              <Terminal className="w-3.5 h-3.5" />
              <span>Runtime Logs</span>
            </button>
          )}
        </div>
      </div>

      {/* ========================================================================= */}
      {/* TAB 1: DASHBOARD CHẨN ĐOÁN & DANH SÁCH ACTION (Gọi /api/ai-debug/analyze) */}
      {/* ========================================================================= */}
      {activeSubTab === 'dashboard' && (
        <div className="space-y-6 animate-in fade-in duration-200">
