                    <span className="text-[11px] text-muted-foreground/70 font-normal">
                      Mô tả triệu chứng cụ thể
                    </span>
                  </label>
                  <input
                    type="text"
                    value={userNote}
                    onChange={(e) => setUserNote(e.target.value)}
