                                {action.env_vars && (
                                  <div className="space-y-1">
                                    <span className="text-[11px] text-muted-foreground block font-sans">
                                      Biến môi trường:
                                    </span>
                                    <pre className="p-2 bg-black/40 rounded border border-border/60 text-emerald-300 text-[11px] overflow-x-auto">
                                      {JSON.stringify(action.env_vars, null, 2)}
                                    </pre>
                                  </div>
                                )}

                                {action.command && (
                                  <div className="space-y-1">
                                    <span className="text-[11px] text-muted-foreground block font-sans">
                                      Câu lệnh thực thi trên Pod:
                                    </span>
                                    <pre className="p-2 bg-black/40 rounded border border-border/60 text-sky-300 text-[11px] overflow-x-auto">
                                      $ {action.command}
                                    </pre>
                                  </div>
                                )}

                                {action.diff && (
                                  <div className="space-y-1">
                                    <span className="text-[11px] text-muted-foreground block font-sans">
                                      Nội dung chỉnh sửa ({action.file_path || 'file'}):
                                    </span>
                                    <pre className="p-2 bg-black/40 rounded border border-border/60 text-zinc-300 text-[11px] overflow-x-auto">
                                      {action.diff}
                                    </pre>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}

                  {/* Nút bấm áp dụng hành động */}
                  {analysis.actions && analysis.actions.length > 0 && (
                    <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pt-3 border-t border-border/70">
                      <span className="text-xs text-muted-foreground">
                        Đã chọn <strong className="text-foreground">{selectedActionIndexes.size}</strong> trên tổng số {analysis.actions.length} hành động đề xuất.
                      </span>

                      <button
                        type="button"
                        onClick={handleExecuteSelected}
                        disabled={selectedActionIndexes.size === 0 || isExecuting}
                        className="flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold transition-all shadow-md active:scale-95 disabled:opacity-50"
                      >
                        {isExecuting ? (
                          <>
                            <Loader2 className="w-4 h-4 animate-spin" />
                            <span>AI DevOps Agent đang thực thi trên cụm K3s...</span>
                          </>
                        ) : (
                          <>
                            <Play className="w-3.5 h-3.5 fill-current" />
                            <span>🚀 Áp dụng các hành động đã chọn ({selectedActionIndexes.size})</span>
                          </>
                        )}
                      </button>
                    </div>
                  )}
                </div>

                {/* Execution Error */}
                {executionError && (
                  <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/20 text-xs text-rose-400 flex items-start gap-3">
                    <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
                    <div className="space-y-1">
                      <span className="font-semibold block">Lỗi thực thi:</span>
                      <span className="opacity-90">{executionError}</span>
                    </div>
                  </div>
                )}

                {/* Kết quả thực thi */}
                {executionResults && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.98 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="bg-card border border-emerald-500/30 rounded-xl p-5 shadow-lg space-y-4"
                  >
                    <div className="flex items-center justify-between pb-3 border-b border-border/70">
                      <div className="flex items-center gap-2.5">
                        <div className="w-8 h-8 rounded-lg bg-emerald-500/15 border border-emerald-500/30 flex items-center justify-center text-emerald-400">
                          <Check className="w-4 h-4" />
                        </div>
                        <div>
                          <h4 className="font-semibold text-sm text-foreground">
                            Kết quả thực thi tự phục hồi (Execution Results)
                          </h4>
                          <p className="text-xs text-muted-foreground">
                            AI DevOps Agent đã hoàn tất thực thi các hành động trên cụm Kubernetes.
                          </p>
                        </div>
                      </div>

                      <span className="text-xs font-semibold px-2.5 py-1 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 flex items-center gap-1">
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        Hoàn tất
                      </span>
                    </div>

                    <div className="space-y-2.5 font-mono text-xs">
                      {executionResults.map((res: any, idx: number) => {
                        const itemResult = res.result || {};
                        const output = String(itemResult.output || res.output || '');
                        const isSuccess = itemResult.status === 'success' || res.status === 'success' || itemResult.success === true;
                        const title = res.action || res.description || res.action_type || `Hành động #${idx + 1}`;
                        const msg = itemResult.message || res.message || (isSuccess ? 'Thành công' : 'Thất bại');

                        return (
                          <div
                            key={idx}
                            className={`p-3.5 rounded-lg border ${
                              isSuccess
                                ? 'bg-emerald-950/20 border-emerald-500/20 text-emerald-300'
                                : 'bg-rose-950/20 border-rose-500/20 text-rose-300'
                            }`}
                          >
                            <div className="flex items-center justify-between mb-1.5 font-sans font-semibold">
                              <span>{title}</span>
                              <span
                                className={`text-[11px] px-2 py-0.5 rounded font-medium ${
                                  isSuccess ? 'bg-emerald-500/20 text-emerald-300' : 'bg-rose-500/20 text-rose-300'
                                }`}
                              >
                                {isSuccess ? 'Thành công' : 'Thất bại'}
                              </span>
                            </div>
                            <div className="text-[11px] opacity-90">{msg}</div>
                            {output && (
                              <pre className="mt-1.5 p-2 bg-black/60 rounded border border-border/40 text-[11px] text-zinc-300 overflow-x-auto whitespace-pre-wrap">
                                {output}
                              </pre>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  </motion.div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      )}

      {/* ========================================================================= */}
      {/* TAB 2: KHUNG CHAT VỚI AI DEVOPS AGENT (Gọi POST /api/ai-debug/chat kèm history) */}
      {/* ========================================================================= */}
      {activeSubTab === 'chat' && (
        <div className="flex flex-col h-[680px] bg-card border border-border rounded-xl shadow-lg overflow-hidden animate-in fade-in duration-200">
          {/* Chat Top Banner / Project Status */}
          <div className="px-5 py-3 bg-muted/20 border-b border-border flex items-center justify-between gap-3 shrink-0">
            <div className="flex items-center gap-2.5">
              <div className="w-8 h-8 rounded-full bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400">
                <Bot className="w-4 h-4" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold text-foreground">AI DevOps Agent Chat Assistant</span>
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" title="Online" />
                </div>
                <span className="text-[11px] text-muted-foreground font-mono">
                  Target: {appName} ({component.toUpperCase()}) • Tự động đọc lại Pod logs mỗi lượt chat
                </span>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <AiProviderSelector
                variant="dropdown"
                value={selectedAiProvider}
                onChange={setSelectedAiProvider}
              />

              {/* Quick link back to Dashboard if actions exist */}
              {analysis?.actions && analysis.actions.length > 0 && (
                <button
                  type="button"
                  onClick={() => setActiveSubTab('dashboard')}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-rose-500/15 hover:bg-rose-500/25 border border-rose-500/30 text-rose-300 text-xs font-medium transition-colors"
                >
                  <span>Xem Action Items ({analysis.actions.length})</span>
                  <ArrowRight className="w-3 h-3" />
                </button>
              )}
            </div>
          </div>

          {/* Chat Messages Stream */}
          <div className="flex-1 overflow-y-auto p-5 space-y-4 custom-scrollbar bg-background/50">
            {chatHistory.map((item, i) => {
              const isUser = item.role === 'user';
              return (
                <div
                  key={i}
                  className={`flex items-start gap-3 ${isUser ? 'justify-end' : 'justify-start'}`}
                >
                  {!isUser && (
                    <div className="w-7 h-7 rounded-full bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 shrink-0 mt-0.5">
                      <Bot className="w-3.5 h-3.5" />
                    </div>
                  )}

                  <div
                    className={`max-w-2xl p-4 rounded-2xl text-xs leading-relaxed shadow-xs ${
                      isUser
                        ? 'bg-indigo-600 text-white rounded-tr-xs'
                        : 'bg-card border border-border text-foreground rounded-tl-xs space-y-2'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-4 text-[10px] pb-1 border-b border-foreground/10 opacity-75">
                      <span className="font-semibold">
                        {isUser ? 'Bạn' : 'AI DevOps Agent'}
                      </span>
                      {item.timestamp && <span>{item.timestamp}</span>}
                    </div>

                    <div className="whitespace-pre-wrap font-sans text-xs leading-relaxed">
                      {item.content}
                    </div>
                  </div>

                  {isUser && (
                    <div className="w-7 h-7 rounded-full bg-indigo-600 text-white flex items-center justify-center shrink-0 mt-0.5 shadow-xs">
                      <User className="w-3.5 h-3.5" />
                    </div>
                  )}
                </div>
              );
            })}

            {/* Typing Loader Indicator */}
            {isChatLoading && (
              <div className="flex items-start gap-3 justify-start">
                <div className="w-7 h-7 rounded-full bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 shrink-0 mt-0.5">
                  <Bot className="w-3.5 h-3.5" />
                </div>
                <div className="bg-card border border-border rounded-2xl rounded-tl-xs p-3.5 text-xs text-muted-foreground flex items-center gap-2 shadow-xs">
                  <Loader2 className="w-3.5 h-3.5 text-indigo-400 animate-spin" />
                  <span className="text-foreground font-medium animate-pulse">
                    AI DevOps Agent đang đọc log Pod mới nhất và suy luận câu trả lời...
                  </span>
                </div>
              </div>
            )}

            <div ref={chatMessagesEndRef} />
          </div>

          {/* Quick Suggestion Chips */}
          <div className="px-5 pt-2 pb-1 bg-card/80 border-t border-border flex items-center gap-1.5 overflow-x-auto custom-scrollbar">
            <span className="text-[11px] text-muted-foreground font-medium shrink-0 mr-1 flex items-center gap-1">
              <Sparkles className="w-3 h-3 text-indigo-400" />
              Gợi ý hỏi nhanh:
            </span>
            {CHAT_QUICK_CHIPS.map((chip, idx) => (
              <button
                key={idx}
                type="button"
                onClick={() => handleSendChatMessage(chip)}
                disabled={isChatLoading}
                className="px-2.5 py-1 rounded-full bg-muted/60 hover:bg-indigo-500/15 hover:text-indigo-300 hover:border-indigo-500/30 border border-border/80 text-[11px] text-muted-foreground shrink-0 transition-colors disabled:opacity-50"
              >
                {chip}
              </button>
            ))}
          </div>

          {/* Chat Input Bar */}
          <div className="p-4 bg-card border-t border-border shrink-0">
            <form
              onSubmit={(e) => {
                e.preventDefault();
                handleSendChatMessage();
              }}
              className="flex items-center gap-2"
            >
              <input
                type="text"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                placeholder="Hỏi AI DevOps Agent về log, nguyên nhân lỗi, cách sửa hoặc thảo luận chi tiết... (Enter để gửi)"
                disabled={isChatLoading}
                className="flex-1 bg-background border border-border rounded-xl px-4 py-2.5 text-xs text-foreground placeholder:text-muted-foreground/60 focus:outline-none focus:border-indigo-500/80 transition-colors disabled:opacity-50 shadow-inner"
              />
              <button
                type="submit"
                disabled={!chatInput.trim() || isChatLoading}
                className="flex items-center gap-1.5 px-4 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-semibold transition-all shadow-md active:scale-95 disabled:opacity-40 shrink-0"
              >
                {isChatLoading ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    <span>Gửi</span>
                    <Send className="w-3.5 h-3.5" />
                  </>
                )}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  Sparkles,
  Bot,
  Zap,
  Cpu,
  CheckCircle2,
  ChevronDown,
  Layers,
  Check,
  Terminal,
} from 'lucide-react';
import { useAiProvider, AiProvider, FALLBACK_AI_PROVIDERS } from '@/lib/useAiProvider';

interface AiProviderSelectorProps {
  variant?: 'cards' | 'toggle' | 'dropdown';
  className?: string;
  // Optional controlled props if parent wants to override
  value?: string;
  onChange?: (providerId: string) => void;
  // Label customizer
  title?: string;
  subtitle?: string;
}

export function getProviderVisual(id: string) {
  if (id === 'claude') {
    return {
      icon: <Terminal className="w-4 h-4" />,
      dotColor: 'bg-amber-500 dark:bg-amber-400',
      iconContainer: 'bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/25',
      badgeClass: 'bg-amber-500/10 text-amber-700 dark:text-amber-300 border border-amber-500/25',
      selectedCard: 'border-amber-500/60 bg-amber-500/5 shadow-xs ring-1 ring-amber-500/30',
      activeCheck: 'text-amber-600 dark:text-amber-400',
      shortTag: 'Opus 5.5',
      shortName: 'Claude Code',
    };
  }
  if (id === 'hermes') {
    return {
      icon: <Bot className="w-4 h-4" />,
      dotColor: 'bg-blue-500 dark:bg-blue-400',
      iconContainer: 'bg-blue-500/15 text-blue-600 dark:text-blue-400 border border-blue-500/25',
      badgeClass: 'bg-blue-500/10 text-blue-700 dark:text-blue-300 border border-blue-500/25',
      selectedCard: 'border-blue-500/60 bg-blue-500/5 shadow-xs ring-1 ring-blue-500/30',
      activeCheck: 'text-blue-600 dark:text-blue-400',
      shortTag: 'Open-Source',
      shortName: 'Hermes Agent',
    };
  }
  // default: 'agy'
  return {
    icon: <Sparkles className="w-4 h-4" />,
    dotColor: 'bg-emerald-500 dark:bg-emerald-400',
    iconContainer: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/25',
    badgeClass: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border border-emerald-500/25',
    selectedCard: 'border-emerald-500/60 bg-emerald-500/5 shadow-xs ring-1 ring-emerald-500/30',
    activeCheck: 'text-emerald-600 dark:text-emerald-400',
    shortTag: 'Nhanh (5-15s)',
    shortName: 'Google Antigravity',
  };
}

export function AiProviderSelector({
  variant = 'cards',
  className = '',
  value,
  onChange,
  title = 'Chọn Bộ não AI Hỗ trợ Triển khai:',
  subtitle = 'Sinh cấu hình Nixpacks & K3s. Hermes Agent tự kiểm tra tổng thể sau khi triển khai',
}: AiProviderSelectorProps) {
  const {
    selectedProvider: hookProvider,
    setProvider: hookSetProvider,
    providers,
    currentProvider: hookCurrentProvider,
  } = useAiProvider();

  // Defensive fallback: ensure claude is guaranteed to be present
  const displayProviders = React.useMemo(() => {
    const list = providers && providers.length > 0 ? providers : FALLBACK_AI_PROVIDERS;
    const hasClaude = list.some((p) => p.id === 'claude');
    if (!hasClaude) {
      const claudeDef = FALLBACK_AI_PROVIDERS.find((p) => p.id === 'claude');
      if (claudeDef) {
        const copy = [...list];
        const agyIndex = copy.findIndex((p) => p.id === 'agy');
        if (agyIndex !== -1) {
          copy.splice(agyIndex + 1, 0, claudeDef);
        } else {
          copy.push(claudeDef);
        }
        return copy;
      }
    }
    return list;
  }, [providers]);

  const selected = value !== undefined ? value : hookProvider;
  const effectiveProvider =
    displayProviders.find((p) => p.id === selected) ||
    hookCurrentProvider ||
    displayProviders[0];

  const handleSelect = (id: string) => {
    if (onChange) {
      onChange(id);
    }
    hookSetProvider(id);
  };

  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setDropdownOpen(false);
      }
    };
    if (dropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [dropdownOpen]);

  const currentVisual = getProviderVisual(selected);

  // ----------------------------------------------------------------------
  // VARIANT: DROPDOWN
  // ----------------------------------------------------------------------
  if (variant === 'dropdown') {
    return (
      <div className={`relative inline-block text-left ${className}`} ref={dropdownRef}>
        <button
          type="button"
          onClick={() => setDropdownOpen(!dropdownOpen)}
          className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-card hover:bg-muted/60 border border-border text-xs font-medium text-foreground transition-all shadow-xs"
          title="Thay đổi AI Engine"
        >
          <div
            className={`w-2 h-2 rounded-full ${currentVisual.dotColor} ${
              selected === 'agy' ? 'animate-pulse' : ''
            }`}
          />
          <span className="font-semibold truncate max-w-[150px]">
            {effectiveProvider?.name || currentVisual.shortName}
          </span>
          <span
            className={`text-[10px] px-1.5 py-0.2 rounded-full font-mono font-normal ${currentVisual.badgeClass}`}
          >
            {currentVisual.shortTag}
          </span>
          <ChevronDown className="w-3 h-3 text-muted-foreground ml-0.5" />
        </button>

        {dropdownOpen && (
          <div className="absolute right-0 mt-1.5 w-80 rounded-xl bg-card border border-border shadow-xl z-50 p-1.5 space-y-1 animate-in fade-in zoom-in-95 duration-100">
            <div className="px-2.5 py-1.5 text-[11px] font-semibold text-muted-foreground border-b border-border/60">
              Chọn AI Reasoning Engine
            </div>
            {displayProviders.map((p) => {
              const isSelected = selected === p.id;
              const visual = getProviderVisual(p.id);
              return (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => {
                    handleSelect(p.id);
                    setDropdownOpen(false);
                  }}
                  className={`w-full text-left p-2.5 rounded-lg transition-all flex items-start gap-2.5 ${
                    isSelected
                      ? 'bg-muted/80 text-foreground ring-1 ring-border'
                      : 'hover:bg-muted/40 text-muted-foreground hover:text-foreground'
                  }`}
                >
                  <div className={`p-1.5 rounded-md shrink-0 mt-0.5 ${visual.iconContainer}`}>
                    {visual.icon}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-1">
                      <span className="text-xs font-semibold text-foreground truncate">
                        {p.name}
                      </span>
                      {isSelected && <Check className="w-3.5 h-3.5 text-foreground shrink-0" />}
                    </div>
                    <span
                      className={`inline-block text-[10px] px-1.5 py-0.2 rounded-full font-mono mt-0.5 ${visual.badgeClass}`}
                    >
                      {p.badge}
                    </span>
                    <p className="text-[11px] text-muted-foreground line-clamp-2 mt-1 leading-snug">
                      {p.description}
                    </p>
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </div>
    );
  }

  // ----------------------------------------------------------------------
  // VARIANT: TOGGLE (Segmented Pill Buttons)
  // ----------------------------------------------------------------------
  if (variant === 'toggle') {
    return (
      <div className={`inline-flex flex-wrap items-center p-1 rounded-xl bg-muted/40 border border-border/80 ${className}`}>
        {displayProviders.map((p) => {
          const isSelected = selected === p.id;
          const visual = getProviderVisual(p.id);
          return (
            <button
              key={p.id}
              type="button"
              onClick={() => handleSelect(p.id)}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                isSelected
                  ? 'bg-background text-foreground shadow-xs border border-border font-semibold'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/30 border border-transparent'
              }`}
            >
              <span className={isSelected ? visual.activeCheck : 'text-muted-foreground'}>
                {visual.icon}
              </span>
              <span>{visual.shortName}</span>
              <span
                className={`text-[10px] px-1.5 py-0.2 rounded-full font-mono ${
                  isSelected ? visual.badgeClass : 'bg-muted text-muted-foreground'
                }`}
              >
                {visual.shortTag}
              </span>
            </button>
          );
        })}
      </div>
    );
  }

  // ----------------------------------------------------------------------
  // VARIANT: CARDS (Radio Cards in Deploy Forms - 2 Columns: Antigravity / Claude Code)
  // ----------------------------------------------------------------------
  return (
    <div className={`flex flex-col gap-3 pt-4 border-t border-border ${className}`}>
      <div className="flex items-center justify-between">
        <label className="text-sm font-medium flex items-center gap-2 text-foreground">
          <div className="p-1 rounded-md bg-amber-500/10 text-amber-400 border border-amber-500/20">
            <Cpu className="w-3.5 h-3.5" />
          </div>
          <span>{title}</span>
        </label>
        <span className="text-[11px] text-muted-foreground hidden sm:inline">
          {subtitle}
        </span>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {displayProviders.map((p) => {
          const isSelected = selected === p.id;
          const visual = getProviderVisual(p.id);
          return (
            <div
              key={p.id}
              onClick={() => handleSelect(p.id)}
              className={`cursor-pointer rounded-xl p-4 border text-left flex flex-col justify-between transition-all relative select-none ${
                isSelected
                  ? visual.selectedCard
                  : 'border-border bg-card/60 hover:border-foreground/30 hover:bg-card text-muted-foreground'
              }`}
            >
              <div>
                <div className="flex items-center justify-between w-full mb-2">
                  <div className="flex items-center gap-2 min-w-0">
                    <div className={`p-1.5 rounded-lg shrink-0 ${visual.iconContainer}`}>
                      {visual.icon}
                    </div>
                    <span className="text-xs font-semibold text-foreground truncate">
                      {p.name}
                    </span>
                  </div>

                  <div className="shrink-0 ml-1.5">
                    {isSelected ? (
                      <CheckCircle2 className={`w-4 h-4 ${visual.activeCheck}`} />
                    ) : (
                      <div className="w-4 h-4 rounded-full border border-border" />
                    )}
                  </div>
                </div>

                <div className="mb-2">
                  <span
                    className={`inline-block text-[10px] px-2 py-0.5 rounded-full font-medium ${visual.badgeClass}`}
                  >
                    {p.badge}
                  </span>
                </div>

                <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2">
                  {p.description}
                </p>
              </div>

              {p.models && p.models.length > 0 && (
                <div className="mt-3 pt-2.5 border-t border-border/50 flex flex-wrap gap-1 items-center">
                  <span className="text-[10px] text-muted-foreground/80 font-mono">
                    Models:
                  </span>
                  {p.models.slice(0, 2).map((m) => (
                    <span
                      key={m}
                      className="text-[10px] px-1.5 py-0.2 rounded bg-muted/60 text-muted-foreground font-mono"
                    >
                      {m.split('/').pop()?.replace(':free', '') || m}
                    </span>
                  ))}
                  {p.models.length > 2 && (
                    <span className="text-[10px] text-muted-foreground font-mono">
                      +{p.models.length - 2}
                    </span>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

