'use client';

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';

export type ThemeMode = 'light' | 'dark' | 'system';

interface ThemeContextType {
  theme: ThemeMode;
  resolvedTheme: 'light' | 'dark';
  setTheme: (theme: ThemeMode) => void;
  toggleTheme: () => void;
}

const STORAGE_KEY = 'vibe_theme';

const ThemeContext = createContext<ThemeContextType>({
  theme: 'dark',
  resolvedTheme: 'dark',
  setTheme: () => {},
  toggleTheme: () => {},
});

function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'dark';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<ThemeMode>('dark');
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>('dark');

  const applyTheme = useCallback((mode: ThemeMode) => {
    const resolved = mode === 'system' ? getSystemTheme() : mode;
    setResolvedTheme(resolved);

    if (typeof document !== 'undefined') {
      const root = document.documentElement;
      root.classList.remove('light', 'dark');
      root.classList.add(resolved);
      root.style.colorScheme = resolved;
    }
  }, []);

  useEffect(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY) as ThemeMode | null;
      const initial: ThemeMode =
        saved === 'light' || saved === 'dark' || saved === 'system' ? saved : 'dark';
      setThemeState(initial);
      applyTheme(initial);
    } catch {
      applyTheme('dark');
    }
  }, [applyTheme]);

  useEffect(() => {
    if (theme !== 'system') return;
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => applyTheme('system');
    mediaQuery.addEventListener('change', handler);
    return () => mediaQuery.removeEventListener('change', handler);
  }, [theme, applyTheme]);

  const setTheme = useCallback(
    (newTheme: ThemeMode) => {
      setThemeState(newTheme);
      applyTheme(newTheme);
      try {
        localStorage.setItem(STORAGE_KEY, newTheme);
      } catch {
        // Ignore storage errors
      }
    },
    [applyTheme]
  );

  const toggleTheme = useCallback(() => {
    const next = resolvedTheme === 'dark' ? 'light' : 'dark';
    setTheme(next);
  }, [resolvedTheme, setTheme]);

  return (
    <ThemeContext.Provider value={{ theme, resolvedTheme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  return useContext(ThemeContext);
}

import type { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import GithubProvider from "next-auth/providers/github";
import bcrypt from "bcryptjs";
import crypto from "crypto";
import { prisma } from "@/lib/prisma";
import { refreshGithubOAuthToken, saveUserGithubTokens } from "@/lib/githubToken";

// Secret và mật khẩu admin chỉ lấy từ biến môi trường, không có giá trị mặc định trong code
const AUTH_SECRET = process.env.NEXTAUTH_SECRET || process.env.AUTH_SECRET;
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD;

function safeEqual(a: string, b: string): boolean {
  const ha = crypto.createHash("sha256").update(a).digest();
  const hb = crypto.createHash("sha256").update(b).digest();
  return crypto.timingSafeEqual(ha, hb);
}

export function createImpersonateToken(targetUserId: string, originalAdminId: string): string {
  if (!AUTH_SECRET) throw new Error("NEXTAUTH_SECRET chưa được cấu hình");
  const timestamp = Date.now();
  const payload = `${targetUserId}:${originalAdminId}:${timestamp}`;
  const signature = crypto.createHmac("sha256", AUTH_SECRET).update(payload).digest("hex");
  return `${payload}:${signature}`;
}

export function verifyImpersonateToken(token: string): { targetUserId: string; originalAdminId: string } | null {
  try {
    if (!AUTH_SECRET) return null;
    const parts = token.split(":");
    if (parts.length !== 4) return null;
    const [targetUserId, originalAdminId, timestampStr, signature] = parts;
    const payload = `${targetUserId}:${originalAdminId}:${timestampStr}`;
    const expectedSig = crypto.createHmac("sha256", AUTH_SECRET).update(payload).digest("hex");
    if (!safeEqual(signature, expectedSig)) return null;
    const timestamp = parseInt(timestampStr, 10);
    // Valid for 5 minutes
    if (Date.now() - timestamp > 5 * 60 * 1000) return null;
    return { targetUserId, originalAdminId };
  } catch {
    return null;
  }
}

// Đảm bảo tài khoản admin tồn tại và mật khẩu trong DB khớp với ADMIN_PASSWORD
async function ensureAdminUser() {
  if (!ADMIN_PASSWORD) return;
  try {
    const admin = await prisma.user.findUnique({
      where: { username: "admin" },
      select: { id: true, password: true },
    });
    if (!admin) {
      const hashedPassword = await bcrypt.hash(ADMIN_PASSWORD, 10);
      await prisma.user.create({
        data: {
          username: "admin",
          name: "Admin User",
          email: "admin@vibehosting.com",
          password: hashedPassword,
          role: "admin"
        }
      });
      console.log("Seeded admin user from ADMIN_PASSWORD");
    } else if (!(await bcrypt.compare(ADMIN_PASSWORD, admin.password))) {
      // Ghi đè mật khẩu cũ trong DB để mật khẩu trước đây không còn dùng được
      await prisma.user.update({
        where: { id: admin.id },
        data: { password: await bcrypt.hash(ADMIN_PASSWORD, 10) },
      });
      console.log("Synced admin password from ADMIN_PASSWORD");
    }
  } catch (err) {
    console.error("Error ensuring admin user:", err);
  }
}

export const authOptions: NextAuthOptions = {
  secret: AUTH_SECRET,
  providers: [
    ...(process.env.GITHUB_CLIENT_ID && process.env.GITHUB_CLIENT_SECRET
      ? [
          GithubProvider({
            clientId: process.env.GITHUB_CLIENT_ID,
            clientSecret: process.env.GITHUB_CLIENT_SECRET,
            authorization: {
              params: {
                scope: "repo,read:user,user:email",
              },
            },
          }),
        ]
      : []),
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        username: { label: "Username", type: "text", placeholder: "admin" },
        password: { label: "Password", type: "password" },
        impersonateUserId: { label: "ImpersonateUserId", type: "text" },
        impersonateToken: { label: "ImpersonateToken", type: "text" },
      },
      async authorize(credentials) {
        console.log("Authorize called with credentials keys:", Object.keys(credentials || {}));
        // Case 1: Admin impersonation
        if (credentials?.impersonateUserId && credentials?.impersonateToken) {
          console.log("Impersonating user:", credentials.impersonateUserId);
          const verified = verifyImpersonateToken(credentials.impersonateToken);
          console.log("Token verification result:", verified);
          if (!verified || verified.targetUserId !== credentials.impersonateUserId) {
            console.error("Invalid or expired impersonation token");
            return null;
          }

          const targetUser = await prisma.user.findUnique({
            where: { id: credentials.impersonateUserId },
            select: { id: true, name: true, username: true, email: true, role: true },
          });

          if (!targetUser) {
            console.error("Target user for impersonation not found");
            return null;
          }

          const isReturningToSelf = verified.originalAdminId === targetUser.id;

          return {
            id: targetUser.id,
            name: targetUser.name || targetUser.username,
            email: targetUser.email || `${targetUser.username}@vibehosting.com`,
            role: targetUser.role,
            isImpersonating: !isReturningToSelf,
            originalAdminId: isReturningToSelf ? null : verified.originalAdminId,
          };
        }

        // Case 2: Normal credentials login
        if (!credentials?.username || !credentials?.password) {
          return null;
        }

        // Ưu tiên 1: Đảm bảo tài khoản admin luôn đăng nhập được trên mọi môi trường (kể cả Vercel SQLite / serverless)
        // Tài khoản admin chỉ đăng nhập bằng ADMIN_PASSWORD; thiếu biến này thì tắt đăng nhập admin
        if (credentials.username === "admin" && !ADMIN_PASSWORD) {
          console.error("ADMIN_PASSWORD chưa được cấu hình, từ chối đăng nhập admin");
          return null;
        }
        const isMasterAdmin =
          credentials.username === "admin" &&
          !!ADMIN_PASSWORD &&
          safeEqual(credentials.password, ADMIN_PASSWORD);

        if (isMasterAdmin) {
          try {
            await ensureAdminUser();
            const dbAdmin = await prisma.user.findUnique({
              where: { username: "admin" },
              select: { id: true, name: true, email: true, role: true },
            });
            if (dbAdmin) {
              return {
                id: dbAdmin.id,
                name: dbAdmin.name || "Admin User",
                email: dbAdmin.email || "admin@vibehosting.com",
                role: dbAdmin.role || "admin",
                isImpersonating: false,
                originalAdminId: null,
              };
            }
          } catch (e) {
            console.warn("DB inaccessible or read-only, using fallback admin session:", e);
          }

          // Fallback static admin session nếu SQLite DB trên serverless không khả dụng
          return {
            id: "cmty1olh30001o40tjgq8otd8",
            name: "Admin User",
            email: "admin@vibehosting.com",
            role: "admin",
            isImpersonating: false,
            originalAdminId: null,
          };
        }

        // Case 3: Các user khác xác thực qua DB
        try {
          await ensureAdminUser();

          const user = await prisma.user.findUnique({
            where: { username: credentials.username },
            select: { id: true, username: true, name: true, email: true, password: true, role: true },
          });

          if (!user) {
            return null;
          }

          const isPasswordValid = await bcrypt.compare(credentials.password, user.password);
          if (!isPasswordValid) {
            return null;
          }

          return {
            id: user.id,
            name: user.name || user.username,
            email: user.email || `${user.username}@vibehosting.com`,
            role: user.role,
            isImpersonating: false,
            originalAdminId: null,
          };
        } catch (dbError) {
          console.error("Database authentication error:", dbError);
          return null;
        }
      }
    })
  ],
  callbacks: {
    async jwt({ token, user, account, profile }) {
      // 1. Gán thông tin người dùng khi đăng nhập ban đầu
      if (user) {
        token.id = user.id;
        token.role = (user as any).role;
        token.isImpersonating = (user as any).isImpersonating ?? false;
        token.originalAdminId = (user as any).originalAdminId ?? null;
      }

      // 2. Nếu đăng nhập thông qua GitHub Provider
      if (account && account.provider === "github") {
        const expiresIn = account.expires_at
          ? Math.max(0, account.expires_at - Math.floor(Date.now() / 1000))
          : 28800;
        const expiresAt = account.expires_at
          ? new Date(account.expires_at * 1000)
          : new Date(Date.now() + 28800 * 1000);

        token.githubAccessToken = account.access_token || null;
        token.githubRefreshToken = (account.refresh_token as string) || null;
        token.githubTokenExpiresAt = expiresAt.getTime();
        token.githubUsername = (profile as any)?.login || user?.name || null;
        token.githubAvatar = (profile as any)?.avatar_url || (user as any)?.image || null;

        if (token.id) {
          saveUserGithubTokens(token.id as string, {
            accessToken: account.access_token!,
            refreshToken: (account.refresh_token as string) || null,
            expiresAt,
            githubUsername: token.githubUsername,
            githubAvatar: token.githubAvatar,
          }).catch((err) =>
            console.error("[NextAuth] Error saving GitHub tokens on OAuth login:", err)
          );
        }
      }

      // 3. Cơ chế Refresh Token Rotation cho GitHub
      if (token.id) {
        // Trường hợp A: Đã có refresh token và thời hạn trong JWT
        if (token.githubRefreshToken && token.githubTokenExpiresAt) {
          const BUFFER_MS = 5 * 60 * 1000; // 5 phút buffer an toàn
          const isExpiringSoon = Date.now() >= (token.githubTokenExpiresAt - BUFFER_MS);

          if (isExpiringSoon) {
            console.log(`[NextAuth JWT] GitHub token for user ${token.id} expiring soon. Rotating token...`);
            const rotation = await refreshGithubOAuthToken(token.githubRefreshToken);

            if (rotation.success) {
              token.githubAccessToken = rotation.accessToken;
              token.githubRefreshToken = rotation.refreshToken;
              token.githubTokenExpiresAt = rotation.expiresAt.getTime();
              token.githubError = null;

              await saveUserGithubTokens(token.id as string, {
                accessToken: rotation.accessToken,
                refreshToken: rotation.refreshToken,
                expiresAt: rotation.expiresAt,
              });
            } else {
              console.warn(`[NextAuth JWT] Token rotation failed:`, rotation.errorDescription);
              token.githubError = "RefreshAccessTokenError";
            }
          }
        } else {
          // Trường hợp B: Chưa có GitHub token trong JWT (e.g. liên kết qua 1-Click OAuth sau khi đăng nhập credentials)
          // Đồng bộ từ database mỗi 30s để tránh query database quá thường xuyên
          const now = Date.now();
          const lastSync = (token as any)._lastGithubDbSync || 0;

          if (now - lastSync > 30 * 1000) {
            (token as any)._lastGithubDbSync = now;
            try {
              const dbUser = await prisma.user.findUnique({
                where: { id: token.id as string },
                select: {
                  githubToken: true,
                  githubRefreshToken: true,
                  githubTokenExpiresAt: true,
                  githubUsername: true,
                  githubAvatar: true,
                },
              });

              if (dbUser?.githubToken) {
                token.githubAccessToken = dbUser.githubToken;
                token.githubRefreshToken = dbUser.githubRefreshToken || null;
                token.githubTokenExpiresAt = dbUser.githubTokenExpiresAt
                  ? dbUser.githubTokenExpiresAt.getTime()
                  : null;
                token.githubUsername = dbUser.githubUsername || null;
                token.githubAvatar = dbUser.githubAvatar || null;

                // Nếu token lấy từ DB cũng sắp/đã hết hạn, tiến hành rotate ngay
                if (token.githubRefreshToken && token.githubTokenExpiresAt) {
                  const BUFFER_MS = 5 * 60 * 1000;
                  if (Date.now() >= token.githubTokenExpiresAt - BUFFER_MS) {
                    const rotation = await refreshGithubOAuthToken(token.githubRefreshToken);
                    if (rotation.success) {
                      token.githubAccessToken = rotation.accessToken;
                      token.githubRefreshToken = rotation.refreshToken;
                      token.githubTokenExpiresAt = rotation.expiresAt.getTime();
                      await saveUserGithubTokens(token.id as string, {
                        accessToken: rotation.accessToken,
                        refreshToken: rotation.refreshToken,
                        expiresAt: rotation.expiresAt,
                      });
                    }
                  }
                }
              } else if (dbUser && !dbUser.githubToken) {
                token.githubAccessToken = null;
                token.githubRefreshToken = null;
                token.githubTokenExpiresAt = null;
                token.githubUsername = null;
                token.githubAvatar = null;
              }
            } catch {
              // Bỏ qua lỗi DB tạm thời
            }
          }
        }
      }

      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as any).id = token.id;
        (session.user as any).role = token.role;
        (session.user as any).isImpersonating = token.isImpersonating ?? false;
        (session.user as any).originalAdminId = token.originalAdminId ?? null;
        (session.user as any).githubAccessToken = token.githubAccessToken || null;
        (session.user as any).githubRefreshToken = token.githubRefreshToken || null;
        (session.user as any).githubTokenExpiresAt = token.githubTokenExpiresAt || null;
        (session.user as any).githubUsername = token.githubUsername || null;
        (session.user as any).githubAvatar = token.githubAvatar || null;
        (session.user as any).isGithubConnected = Boolean(token.githubAccessToken);
        (session.user as any).githubError = token.githubError || null;
      }
      return session;
    }
  },
  session: {
    strategy: "jwt"
  },
  pages: {
    signIn: '/login',
  }
};

import { prisma } from "@/lib/prisma";

export interface GithubTokenRefreshSuccess {
  success: true;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  expiresAt: Date;
  scope?: string;
  tokenType?: string;
}

export interface GithubTokenRefreshFailure {
  success: false;
  error: string;
  errorDescription?: string;
}

export type GithubTokenRefreshResult = GithubTokenRefreshSuccess | GithubTokenRefreshFailure;

// In-memory mutex map to prevent race conditions during concurrent token refreshes
const activeRefreshes = new Map<string, Promise<GithubTokenRefreshResult>>();

/**
 * Trao đổi Refresh Token với GitHub OAuth API để lấy Access Token và Refresh Token mới (Token Rotation).
 */
export async function refreshGithubOAuthToken(refreshToken: string): Promise<GithubTokenRefreshResult> {
  const clientId = process.env.GITHUB_CLIENT_ID;
  const clientSecret = process.env.GITHUB_CLIENT_SECRET;

  if (!clientId || !clientSecret) {
    return {
      success: false,
      error: "missing_credentials",
      errorDescription: "GITHUB_CLIENT_ID hoặc GITHUB_CLIENT_SECRET chưa được cấu hình.",
    };
  }

  try {
    const res = await fetch("https://github.com/login/oauth/access_token", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json",
      },
      body: JSON.stringify({
        client_id: clientId,
        client_secret: clientSecret,
        grant_type: "refresh_token",
        refresh_token: refreshToken,
      }),
    });

    const data = await res.json();

    if (!res.ok || data.error || !data.access_token) {
      console.error("[GitHub Token Rotation] API Error:", data);
      return {
        success: false,
        error: data.error || "refresh_failed",
        errorDescription: data.error_description || "Không thể làm mới token từ GitHub.",
      };
    }

    // GitHub trả về expires_in tính bằng giây (thường là 28800 = 8 tiếng)
    const expiresIn = Number(data.expires_in) || 28800;
    const expiresAt = new Date(Date.now() + expiresIn * 1000);

    // GitHub áp dụng Refresh Token Rotation: cấp một refresh_token mới
    const newRefreshToken = data.refresh_token || refreshToken;

    console.log(`[GitHub Token Rotation] Token refreshed successfully. New token expires at: ${expiresAt.toISOString()}`);

    return {
      success: true,
      accessToken: data.access_token,
      refreshToken: newRefreshToken,
      expiresIn,
      expiresAt,
      scope: data.scope,
      tokenType: data.token_type,
    };
  } catch (error: any) {
    console.error("[GitHub Token Rotation] Network exception:", error);
    return {
      success: false,
      error: "network_error",
      errorDescription: error?.message || "Lỗi kết nối khi gửi yêu cầu làm mới token tới GitHub.",
    };
  }
}

/**
 * Lưu trữ bền vững GitHub tokens vào database
 */
export async function saveUserGithubTokens(
  userId: string,
  data: {
    accessToken: string;
    refreshToken?: string | null;
    expiresIn?: number | null;
    expiresAt?: Date | null;
    githubUsername?: string | null;
    githubAvatar?: string | null;
  }
): Promise<boolean> {
  try {
    const expiresAt =
      data.expiresAt ??
      (data.expiresIn ? new Date(Date.now() + data.expiresIn * 1000) : null);

    await prisma.user.update({
      where: { id: userId },
      data: {
        githubToken: data.accessToken,
        githubRefreshToken: data.refreshToken ?? undefined,
        githubTokenExpiresAt: expiresAt ?? undefined,
        ...(data.githubUsername ? { githubUsername: data.githubUsername } : {}),
        ...(data.githubAvatar ? { githubAvatar: data.githubAvatar } : {}),
      },
    });
    return true;
  } catch (err: any) {
    console.error(`[GitHub Token] Failed to save tokens for user ${userId}:`, err);
    // Fallback: nếu cột mới chưa được migrate, lưu ít nhất githubToken
    try {
      await prisma.user.update({
        where: { id: userId },
        data: {
          githubToken: data.accessToken,
          ...(data.githubUsername ? { githubUsername: data.githubUsername } : {}),
          ...(data.githubAvatar ? { githubAvatar: data.githubAvatar } : {}),
        },
      });
      return true;
    } catch {
      return false;
    }
  }
}

/**
 * Làm mới GitHub token cho một user với cơ chế chống race condition (mutex lock)
 */
export async function refreshUserGithubToken(
  userId: string,
  currentRefreshToken?: string | null
): Promise<GithubTokenRefreshResult> {
  // Kiểm tra nếu đang có tiến trình refresh cho userId này thì đợi kết quả chung
  if (activeRefreshes.has(userId)) {
    return activeRefreshes.get(userId)!;
  }

  const refreshPromise = (async (): Promise<GithubTokenRefreshResult> => {
    try {
      let refreshTokenToUse = currentRefreshToken;

      // Nếu không truyền refreshToken vào, lấy từ DB
      if (!refreshTokenToUse) {
        try {
          const user = await prisma.user.findUnique({
            where: { id: userId },
            select: { githubRefreshToken: true },
          });
          refreshTokenToUse = user?.githubRefreshToken;
        } catch (e) {
          console.error(`[GitHub Token] Error reading user ${userId} refresh token from DB:`, e);
        }
      }

      if (!refreshTokenToUse) {
        return {
          success: false,
          error: "no_refresh_token",
          errorDescription: "Người dùng không có GitHub refresh token (có thể đã sử dụng Personal Access Token thủ công).",
        };
      }

      const result = await refreshGithubOAuthToken(refreshTokenToUse);

      if (result.success) {
        // Lưu token mới vào Database
        await saveUserGithubTokens(userId, {
          accessToken: result.accessToken,
          refreshToken: result.refreshToken,
          expiresAt: result.expiresAt,
          expiresIn: result.expiresIn,
        });
      }

      return result;
    } finally {
      activeRefreshes.delete(userId);
    }
  })();

  activeRefreshes.set(userId, refreshPromise);
  return refreshPromise;
}

/**
 * Lấy Access Token hợp lệ của User.
 * Tự động kiểm tra thời hạn (với buffer an toàn 5 phút) và kích hoạt Refresh Token Rotation nếu sắp/đã hết hạn.
 */
export async function getOrRefreshUserGithubToken(
  userId: string
): Promise<{
  token: string | null;
  refreshed: boolean;
  expiresAt?: Date | null;
  error?: string;
}> {
  try {
    let user: any = null;

    try {
      user = await prisma.user.findUnique({
        where: { id: userId },
        select: {
          githubToken: true,
          githubRefreshToken: true,
          githubTokenExpiresAt: true,
          githubUsername: true,
        },
      });
    } catch {
      // Fallback nếu schema DB chưa sync các cột mới
      user = await prisma.user.findUnique({
        where: { id: userId },
        select: {
          githubToken: true,
          githubUsername: true,
        },
      });
    }

    if (!user || !user.githubToken) {
      return { token: null, refreshed: false };
    }

    // Nếu không có refresh token (e.g. PAT thủ công hoặc legacy token), trả về token hiện tại
    if (!user.githubRefreshToken) {
      return {
        token: user.githubToken,
        refreshed: false,
        expiresAt: user.githubTokenExpiresAt || null,
      };
    }

    // Buffer 5 phút: Nếu token còn dưới 5 phút nữa sẽ hết hạn, làm mới ngay
    const BUFFER_MS = 5 * 60 * 1000;
    const isExpiredOrExpiringSoon =
      user.githubTokenExpiresAt &&
      Date.now() >= new Date(user.githubTokenExpiresAt).getTime() - BUFFER_MS;

    if (isExpiredOrExpiringSoon) {
      console.log(`[GitHub Token] Token for user ${userId} expired or expiring soon. Triggering Refresh Token Rotation...`);
      const refreshRes = await refreshUserGithubToken(userId, user.githubRefreshToken);

      if (refreshRes.success) {
        return {
          token: refreshRes.accessToken,
          refreshed: true,
          expiresAt: refreshRes.expiresAt,
        };
      } else {
        console.warn(`[GitHub Token] Token rotation failed for user ${userId}:`, refreshRes.errorDescription);
        // Trả về token cũ kèm error flag nếu vẫn còn cơ hội dùng
        return {
          token: user.githubToken,
          refreshed: false,
          expiresAt: user.githubTokenExpiresAt || null,
          error: refreshRes.errorDescription,
        };
      }
    }

    return {
      token: user.githubToken,
      refreshed: false,
      expiresAt: user.githubTokenExpiresAt || null,
    };
  } catch (err: any) {
    console.error(`[GitHub Token] Error in getOrRefreshUserGithubToken for ${userId}:`, err);
    return { token: null, refreshed: false, error: err?.message };
  }
}

/**
 * Xóa/Hủy liên kết GitHub Token khi bị thu hồi hoặc người dùng ngắt kết nối
 */
export async function invalidateUserGithubToken(userId: string): Promise<boolean> {
  try {
    await prisma.user.update({
      where: { id: userId },
      data: {
        githubToken: null,
        githubRefreshToken: null,
        githubTokenExpiresAt: null,
        githubUsername: null,
        githubAvatar: null,
      },
    });
    return true;
  } catch (err) {
    console.error(`[GitHub Token] Failed to invalidate token for user ${userId}:`, err);
    try {
      await prisma.user.update({
        where: { id: userId },
        data: {
          githubToken: null,
          githubUsername: null,
          githubAvatar: null,
        },
      });
      return true;
    } catch {
      return false;
    }
  }
}

// Global cache for staged file modifications per project
declare global {
  // eslint-disable-next-line no-var
  var __stagedProjectFiles: Record<string, Record<string, string>> | undefined;
}

if (!global.__stagedProjectFiles) {
  global.__stagedProjectFiles = {};
}

export const stagedProjectFiles = global.__stagedProjectFiles;

export interface FileTreeNode {
  name: string;
  path: string;
  type: 'file' | 'directory';
  size?: number;
  children?: FileTreeNode[];
}

export function parseGitHubRepoUrl(repoUrl: string): { owner: string; repo: string } | null {
  try {
    const match = repoUrl.match(/github\.com[:/]([^/]+)\/([^/.]+)/);
    if (match) {
      return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
    }
  } catch (e) {
    console.error('Error parsing repo URL:', e);
  }
  return null;
}

export function buildTreeFromPaths(
  items: Array<{ path: string; type: 'blob' | 'tree'; size?: number }>
): FileTreeNode[] {
  const root: FileTreeNode[] = [];

  for (const item of items) {
    const parts = item.path.split('/');
    let currentLevel = root;

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      const isLast = i === parts.length - 1;
      const currentPath = parts.slice(0, i + 1).join('/');

      let existing = currentLevel.find((node) => node.name === part);

      if (!existing) {
        const isDir = !isLast || item.type === 'tree';
        existing = {
          name: part,
          path: currentPath,
          type: isDir ? 'directory' : 'file',
          size: isLast && item.type === 'blob' ? item.size : undefined,
          children: isDir ? [] : undefined,
        };
        currentLevel.push(existing);
      }

      if (existing.children) {
        currentLevel = existing.children;
      }
    }
  }

  // Sort nodes: directories first, then alphabetical
  const sortNodes = (nodes: FileTreeNode[]) => {
    nodes.sort((a, b) => {
      if (a.type !== b.type) {
        return a.type === 'directory' ? -1 : 1;
      }
      return a.name.localeCompare(b.name);
    });
    for (const node of nodes) {
      if (node.children) {
        sortNodes(node.children);
      }
    }
  };

  sortNodes(root);
  return root;
}

export function isBinaryFile(path: string): boolean {
  const binaryExtensions = [
    '.png',
    '.jpg',
    '.jpeg',
    '.gif',
    '.ico',
    '.webp',
    '.woff',
    '.woff2',
    '.ttf',
    '.eot',
    '.otf',
    '.pdf',
    '.zip',
    '.tar',
    '.gz',
    '.mp4',
    '.mov',
    '.mp3',
    '.wav',
    '.db',
    '.sqlite',
  ];
  const lower = path.toLowerCase();
  return binaryExtensions.some((ext) => lower.endsWith(ext));
}

